//! Song select's preview movie on desktop (feature `video`,
//! `docs/plans/lane-covers.md`, "Preview video"): a song folder made here
//! (`#PREVIEWVID` naming an H.264 clip of a color turning round the hue
//! wheel, generated by the `ffmpeg` command), listed by the library's
//! scan, selected on song select and drawn offscreen: once the selection
//! has settled its frames come into the banner's place and keep changing;
//! another song selected stops it. Skipped without a GPU adapter, the
//! `ffmpeg` command or the video helper. `DDI_OFFSCREEN_PPM=<dir>` keeps
//! the pictures.
#![cfg(feature = "video")]

mod common;
use std::path::Path;
use std::rc::Rc;

use ddi_desktop::gpu::{self, Gpu};
use ddi_desktop::songs::Songs;
use ddi_ui::UiEvent;
use ddi_ui::screens::select::PREVIEW_MOVIE;
use ddi_ui::state::place::MenuPlace;

fn ffmpeg(args: &[&str]) -> bool {
    std::process::Command::new("ffmpeg")
        .args(["-hide_banner", "-loglevel", "error", "-y"])
        .args(args)
        .status()
        .is_ok_and(|s| s.success())
}

const SSC: &str = "#VERSION:0.83;#TITLE:Preview Movie;#ARTIST:Test;#MUSIC:music.wav;\
#PREVIEWVID:Preview.mp4;#OFFSET:0;#BPMS:0=120;#SAMPLESTART:0;#SAMPLELENGTH:4;\
#NOTEDATA:;#STEPSTYPE:dance-single;#DIFFICULTY:Easy;#METER:1;#NOTES:\n\
1000\n0100\n0010\n0001\n;";

/// The song folder, or `None` without `ffmpeg`.
fn song(dir: &Path) -> Option<()> {
    let song = dir.join("Pack/Preview Movie");
    std::fs::create_dir_all(&song).ok()?;
    std::fs::write(song.join("song.ssc"), SSC).ok()?;
    let clip = song.join("Preview.mp4");
    let music = song.join("music.wav");
    (ffmpeg(&[
        "-f",
        "lavfi",
        "-i",
        "color=c=red:s=320x180:r=30:d=3,hue=h=t*120:s=1",
        "-c:v",
        "libx264",
        "-pix_fmt",
        "yuv420p",
        "-movflags",
        "+faststart",
        clip.to_str()?,
    ]) && ffmpeg(&[
        "-f",
        "lavfi",
        "-i",
        "anullsrc=r=44100:cl=stereo",
        "-t",
        "6",
        music.to_str()?,
    ]))
    .then_some(())
}

#[test]
fn the_preview_movie_plays_in_the_banners_place() {
    common::indexes();
    let home = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../target/scratch/preview-movie-offscreen/home");
    let _ = std::fs::remove_dir_all(&home);
    // SAFETY: set before any thread of this test reads the environment.
    unsafe { std::env::set_var("DDI_HOME", &home) };
    ddi_desktop::audio::set_headless(true);
    let instance = gpu::instance();
    let Some(adapter) = gpu::adapter(&instance, None) else {
        eprintln!("no GPU adapter: skipped");
        return;
    };
    if ddi_desktop::video::helper_path().is_none() {
        eprintln!("no video helper: skipped");
        return;
    }
    let dir = home.join("../songs");
    if song(&dir).is_none() {
        eprintln!("no ffmpeg: skipped");
        return;
    }
    let (device, queue) = gpu::device(&adapter).expect("device");
    let format = wgpu::TextureFormat::Rgba8Unorm;
    let mut gpu = Gpu::new(device, queue, format);
    let wake: std::sync::Arc<dyn Fn() + Send + Sync> = std::sync::Arc::new(|| {});
    // The library scanned once (its cache kept), the song's id found and
    // kept as the list's place: the next song select shows it.
    let id = {
        let songs = Songs::new(vec![dir.clone()]);
        songs.skip_offer();
        songs.start(wake.clone());
        let started = std::time::Instant::now();
        loop {
            let id = songs.library.borrow().as_ref().and_then(|l| {
                (!l.scanning)
                    .then(|| l.songs.iter().find(|s| s.entry.title == "Preview Movie"))
                    .flatten()
                    .map(|s| s.entry.id.clone())
            });
            if let Some(id) = id {
                break id;
            }
            let mut ui = ddi_ui::Ui::new(ddi_ui::screens::DESIGN, ddi_ui::TextMode::Own, true);
            songs.poll(&mut ui);
            assert!(started.elapsed().as_secs() < 30, "the scan never ended");
            std::thread::sleep(std::time::Duration::from_millis(20));
        }
    };
    MenuPlace {
        known: true,
        song: Some(id.clone()),
        chart: Some((id.clone(), 0)),
        ..MenuPlace::default()
    }
    .save();
    let songs = Songs::new(vec![dir.clone()]);
    songs.skip_offer();
    songs.start(wake);
    let fold: ddi_ui::dev_widgets::FoldFn = Rc::new(|s: &str| s.to_lowercase());
    let sound = Rc::new(std::cell::RefCell::new(ddi_desktop::preview::Player::with(
        ddi_desktop::audio::Audio::silent(0.0),
        ddi_desktop::preview::PreviewSong::bundled,
    )));
    let (mut ui, env, _) = ddi_desktop::shell::library_ui("select", fold, sound, &songs);
    ui.handle(UiEvent::Resize {
        size: [1280.0, 720.0],
        ratio: 1.0,
    });
    let keep = |name: &str, pixels: &[u8]| {
        if let Some(dir) = std::env::var_os("DDI_OFFSCREEN_PPM") {
            let mut ppm = b"P6\n1280 720\n255\n".to_vec();
            ppm.extend(
                pixels
                    .as_chunks::<4>()
                    .0
                    .iter()
                    .flat_map(|p| [p[0], p[1], p[2]]),
            );
            std::fs::write(Path::new(&dir).join(name), ppm).expect("ppm");
        }
    };
    let banner_source = |ui: &ddi_ui::Ui| {
        let mut info = ui.actor("Info")?.clone();
        let a = ddi_ui::widgets::part(&mut info, "Banner")?;
        let ddi_actor::Kind::Sprite(s) = &a.kind else {
            return None;
        };
        a.visible
            .then(|| ui.texture_source(s.texture))
            .flatten()
            .map(|t| t.source.to_string())
    };
    // The banner's place, from the actor drawn there: its mean color.
    let mean = |ui: &ddi_ui::Ui, pixels: &[u8]| -> [u32; 3] {
        let [x0, y0, x1, y1] = ui.bounds("Info").expect("the song's side");
        let (x0, y0) = (x0.max(0.0) as u32 + 8, y0.max(0.0) as u32 + 8);
        let (x1, y1) = ((x0 + 200).min(x1 as u32), (y0 + 60).min(y1 as u32));
        let mut sum = [0u64; 3];
        let mut n = 0;
        for y in y0..y1 {
            for x in x0..x1 {
                let i = ((y * 1280 + x) * 4) as usize;
                for c in 0..3 {
                    sum[c] += u64::from(pixels[i + c]);
                }
                n += 1;
            }
        }
        sum.map(|s| (s / n.max(1)) as u32)
    };
    let frame = |ui: &mut ddi_ui::Ui, gpu: &mut Gpu| {
        songs.poll(ui);
        ui.update(1.0 / 60.0);
        gpu.movie.follow(ui, &env, Some(&songs.feed));
        let pixels = gpu.draw_offscreen(ui, [1280, 720], format);
        std::thread::sleep(std::time::Duration::from_millis(16));
        pixels
    };
    // Settling, then the first frame (the helper starting takes a while).
    let started = std::time::Instant::now();
    let mut pixels = Vec::new();
    while gpu.movie.state().frames() < 5 {
        pixels = frame(&mut ui, &mut gpu);
        assert!(
            started.elapsed().as_secs() < 30,
            "no frame came: {:?}",
            gpu.movie.state()
        );
    }
    assert_eq!(env.state.borrow().song_id, id);
    assert_eq!(gpu.movie.state().showing(), Some(id.as_str()));
    assert!(gpu.movie.busy());
    // Song select told: the banner's place shows the movie.
    for _ in 0..3 {
        pixels = frame(&mut ui, &mut gpu);
    }
    assert_eq!(banner_source(&ui).as_deref(), Some(PREVIEW_MOVIE));
    keep("preview-movie-1.ppm", &pixels);
    let first = mean(&ui, &pixels);
    // A second on, the hue moved on.
    for _ in 0..50 {
        pixels = frame(&mut ui, &mut gpu);
    }
    keep("preview-movie-2.ppm", &pixels);
    let later = mean(&ui, &pixels);
    let moved: u32 = first.iter().zip(later).map(|(a, b)| a.abs_diff(b)).sum();
    assert!(moved > 60, "the picture changed: {first:?} → {later:?}");
    assert!(gpu.movie.state().frames() > 20, "{:?}", gpu.movie.state());
    // Another song: the movie stops, its banner shows.
    for key in ["ArrowUp", "ArrowDown", "ArrowDown"] {
        if env.state.borrow().song_id != id {
            break;
        }
        ui.handle(UiEvent::Key(ddi_ui::event::KeyEvent::down(key, key)));
        ui.handle(UiEvent::Key(ddi_ui::event::KeyEvent::up(key, key)));
        for _ in 0..30 {
            frame(&mut ui, &mut gpu);
        }
    }
    assert_ne!(env.state.borrow().song_id, id);
    assert_eq!(gpu.movie.state().showing(), None);
    assert!(!gpu.movie.busy());
    assert_ne!(banner_source(&ui).as_deref(), Some(PREVIEW_MOVIE));
    let _ = std::fs::remove_dir_all(&dir);
}
